with with_prev as (select *, lag(paid_at) over (partition by method order by paid_at, id) as prev_paid_at from payments), flagged as (select *, case when prev_paid_at is null or paid_at > prev_paid_at + interval '14' day then 1 else 0 end as is_new_burst from with_prev) select id, order_id, method, amount, paid_at, status, sum(is_new_burst) over (partition by method order by paid_at, id rows between unbounded preceding and current row) as island_id from flagged
